//! Existing standard-library mode, with the full feature closure enabled.
use std::{sync::{Arc,atomic::{AtomicUsize,Ordering}},time::Duration};
use tokio::io::{AsyncReadExt,AsyncWriteExt};
tokio::task_local!{static VALUE:usize;}
fn test(name:&str,f:impl FnOnce()){f();println!("ok {name}");}
fn current()->tokio::runtime::Runtime{tokio::runtime::Builder::new_current_thread().enable_all().build().unwrap()}
struct Dropped(Arc<AtomicUsize>);impl Drop for Dropped{fn drop(&mut self){self.0.fetch_add(1,Ordering::SeqCst);}}
fn main(){
 test("std current scheduler channels timer",||{current().block_on(async{let(tx,mut rx)=tokio::sync::mpsc::channel(1);let j=tokio::spawn(async move{tokio::time::sleep(Duration::from_millis(2)).await;tx.send(42).await.unwrap();});assert_eq!(rx.recv().await,Some(42));j.await.unwrap();});});
 test("std task panic retained in JoinError",||{current().block_on(async{let j=tokio::spawn(async{panic!("expected task panic");});let e=j.await.unwrap_err();assert!(e.is_panic());let p=e.into_panic();assert_eq!(*p.downcast::<&'static str>().unwrap(),"expected task panic");});});
 test("std blocking panic retained",||{current().block_on(async{let e=tokio::task::spawn_blocking(||panic!("expected blocking panic")).await.unwrap_err();assert!(e.is_panic());});});
 test("std aborted task runs destructor",||{let count=Arc::new(AtomicUsize::new(0));current().block_on(async{let c=count.clone();let j=tokio::spawn(async move{let _drop=Dropped(c);std::future::pending::<()>().await;});tokio::task::yield_now().await;j.abort();assert!(j.await.unwrap_err().is_cancelled());});assert_eq!(count.load(Ordering::SeqCst),1);});
 test("std tasklocal and localset affinity",||{let local=tokio::task::LocalSet::new();let value=std::rc::Rc::new(std::cell::Cell::new(0));let v=value.clone();local.block_on(&current(),VALUE.scope(5,async move{let j=tokio::task::spawn_local(async move{v.set(5);});j.await.unwrap();assert_eq!(VALUE.get(),5);}));assert_eq!(value.get(),5);assert!(VALUE.try_with(|_|()).is_err());});
 test("std paused time clock conversion",||{tokio::runtime::Builder::new_current_thread().enable_time().start_paused(true).build().unwrap().block_on(async{let before=tokio::time::Instant::now();tokio::time::sleep(Duration::from_secs(10)).await;let after=tokio::time::Instant::now();assert!(after-before>=Duration::from_secs(10));let raw=after.into_std();assert_eq!(tokio::time::Instant::from_std(raw),after);});});
 test("std multithread work and timer wakes",||{let rt=tokio::runtime::Builder::new_multi_thread().worker_threads(2).enable_all().build().unwrap();rt.block_on(async{let mut jobs=Vec::new();for i in 0..64{jobs.push(tokio::spawn(async move{tokio::task::yield_now().await;i}));}let mut sum=0;for j in jobs{sum+=j.await.unwrap();}assert_eq!(sum,(0..64).sum::<usize>());});});
 test("std duplex and cursor vectored writes",||{current().block_on(async{let(mut a,mut b)=tokio::io::duplex(2);let j=tokio::spawn(async move{a.write_all(b"abcdef").await.unwrap();a.shutdown().await.unwrap();});let mut out=Vec::new();b.read_to_end(&mut out).await.unwrap();j.await.unwrap();assert_eq!(out,b"abcdef");let mut c=std::io::Cursor::new(Vec::new());c.set_position(2);let slices=[std::io::IoSlice::new(b"ab"),std::io::IoSlice::new(b"cd")];assert_eq!(c.write_vectored(&slices).await.unwrap(),4);assert_eq!(c.into_inner(),b"\0\0abcd");});});
 test("std actual TCP loopback Mio path",||{current().block_on(async{let listener=tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();let addr=listener.local_addr().unwrap();let server=tokio::spawn(async move{let(mut stream,_)=listener.accept().await.unwrap();let mut buf=[0;4];stream.read_exact(&mut buf).await.unwrap();assert_eq!(&buf,b"ping");stream.write_all(b"pong").await.unwrap();});let mut stream=tokio::net::TcpStream::connect(addr).await.unwrap();stream.write_all(b"ping").await.unwrap();let mut buf=[0;4];stream.read_exact(&mut buf).await.unwrap();assert_eq!(&buf,b"pong");server.await.unwrap();});});
 test("std fs and process remain functional",||{current().block_on(async{let path=std::env::temp_dir().join(format!("trueos-tokio-compat-{}",std::process::id()));tokio::fs::write(&path,b"native-boundary").await.unwrap();assert_eq!(tokio::fs::read(&path).await.unwrap(),b"native-boundary");tokio::fs::remove_file(path).await.unwrap();let output=tokio::process::Command::new("/bin/echo").arg("hello").output().await.unwrap();assert!(output.status.success());assert_eq!(output.stdout,b"hello\n");});});
 println!("10 std-compat behavior cases passed");
}
